/**
 *
 * TooltipPositioner is a component that positions the tooltip popup.
 *
 * [Live Demo](https://www.primereact.org/tooltip/)
 *
 * @module TooltipPositioner
 * @group components
 *
 */
import type { ComponentInstance } from '@primereact/types/core';
import type { BaseComponentProps, PassThroughType } from '../..';
import type { UsePositionerProps } from '@primereact/types/headless/positioner';
import type { TooltipRootInstance } from './TooltipRoot.types';
/**
 * Defines passthrough(pt) options type in TooltipPositioner component.
 */
export type TooltipPositionerPassThroughType<E> = PassThroughType<TooltipPositionerInstance, E>;
/**
 * Defines passthrough(pt) options of TooltipPositioner component.
 */
export interface TooltipPositionerPassThrough {
    /**
     * Used to pass attributes to the root's DOM element.
     */
    root?: TooltipPositionerPassThroughType<React.HTMLAttributes<HTMLDivElement>>;
}
/**
 * Defines valid properties in TooltipPositioner component.
 */
export interface TooltipPositionerProps extends BaseComponentProps<TooltipPositionerInstance, UsePositionerProps, TooltipPositionerPassThrough> {
}
/**
 * Defines valid state in TooltipPositioner component.
 */
export interface TooltipPositionerState {
}
/**
 * Defines the methods and properties exposed by TooltipPositioner component.
 */
export interface TooltipPositionerExposes {
    /**
     * The Tooltip component instance.
     */
    tooltip: TooltipRootInstance | undefined | null;
}
/**
 * Instance of TooltipPositioner component.
 */
export type TooltipPositionerInstance = ComponentInstance<TooltipPositionerProps, TooltipPositionerState, TooltipPositionerExposes>;
